void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    slow_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;
    // Reset activity increment to avoid overflow and give fresh VSIDS scores
    var_inc = 1.0;
    // Backtrack completely to root level
    backtrack(0);
    // Re‑phase variables: majority keep the best local phase, some are inverted,
    // and a small fraction are assigned randomly.
    int r = rand() % 100;
    if (r < 70) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 85) {
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }
}
